"""Desktop notifications: generated by the worker every minute, delivered when the desktop asks.

Deterministic, pt-PT, built only from stored data. Each notification has a stable key, so a rule can
fire every minute without duplicates, and an expiry, so nothing stale appears after the PC was off.
"""

from collections.abc import Iterable
from datetime import date, datetime, time, timedelta
from zoneinfo import ZoneInfo

from pydantic import BaseModel, ConfigDict, Field
from sqlalchemy import Integer, and_, case, func, or_, select
from sqlalchemy.dialects.postgresql import insert
from sqlalchemy.orm import Session

from peace import sync
from peace.knowledge import load_index, suggest, suggest_text
from peace.models import OPEN_STATUSES, Change, Event, Notification, Preference, StudySession, Task
from peace.planner import PlanPrefs


class NotifyPrefs(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid")

    enabled: bool = True
    quiet_start: time = time(23, 0)
    quiet_end: time = time(8, 0)
    briefing_at: time = time(8, 0)
    deadlines: bool = True
    sessions: bool = True
    changes: bool = True
    missed: bool = True
    integrations: bool = True
    # Rate limit for low-priority kinds (LOW_PRIORITY); deadlines, exams, sessions and the briefing are on time.
    max_per_hour: int = Field(4, ge=1, le=30)
    min_gap_minutes: int = Field(10, ge=0, le=120)


def notify_prefs(session: Session) -> NotifyPrefs:
    row = session.get(Preference, "notifications")
    return NotifyPrefs.model_validate(row.value) if row else NotifyPrefs()


def planner_prefs(session: Session) -> PlanPrefs:
    row = session.get(Preference, "planner")
    return PlanPrefs.model_validate(row.value) if row else PlanPrefs()


LOW_PRIORITY = ("changes", "missed", "integration")


def low_priority_budget(session: Session, now: datetime, prefs: NotifyPrefs) -> int:
    """How many low-priority notifications may be shown now (0 over the hourly budget or within the gap)."""
    recent = list(session.scalars(select(Notification.delivered_at).where(
        Notification.kind.in_(LOW_PRIORITY), Notification.urgent.is_(False),
        Notification.delivered_at >= now - timedelta(hours=1))))
    if recent and max(recent) > now - timedelta(minutes=prefs.min_gap_minutes):
        return 0
    return prefs.max_per_hour - len(recent)


def rate_limited(rows: Iterable[Notification], allowed: int, prefs: NotifyPrefs) -> list[Notification]:
    """Keep low-priority notifications within the budget (the rest stay pending)."""
    out = []
    for n in rows:
        if n.kind in LOW_PRIORITY and not n.urgent:
            if allowed <= 0:
                continue
            allowed = 0 if prefs.min_gap_minutes else allowed - 1  # with a gap, one per batch
        out.append(n)
        if len(out) >= 20:
            break
    return out


def focus_until(session: Session, now: datetime) -> datetime | None:
    """End of the running focus mode, or None (set by peace.assistant)."""
    row = session.get(Preference, "focus")
    until = datetime.fromisoformat(row.value["until"]) if row and row.value.get("until") else None
    return until if until and until > now else None


def in_quiet_hours(now: datetime, tz: ZoneInfo, prefs: NotifyPrefs) -> bool:
    t, start, end = now.astimezone(tz).time(), prefs.quiet_start, prefs.quiet_end
    return (t >= start or t < end) if start > end else start <= t < end


def _plural(n: int, one: str, many: str) -> str:
    return f"{n} {one if n == 1 else many}"


def _join(parts: list[str]) -> str:
    return parts[0] if len(parts) == 1 else f"{', '.join(parts[:-1])} e {parts[-1]}"


WEEKDAYS = ["segunda", "terça", "quarta", "quinta", "sexta", "sábado", "domingo"]


def _when(at: datetime, now: datetime, tz: ZoneInfo) -> str:
    local, today = at.astimezone(tz), now.astimezone(tz).date()
    days = (local.date() - today).days
    day = "hoje" if days == 0 else "amanhã" if days == 1 else WEEKDAYS[local.weekday()]
    return f"{day} às {local:%H:%M}"


def _add(session: Session, **values) -> bool:
    """Insert, re-arm a changed deadline, or refresh pending text (concurrency-safe)."""
    stmt = insert(Notification).values(**values)
    changed_date = Notification.expires_at.is_distinct_from(stmt.excluded.expires_at)
    pending_text = and_(Notification.delivered_at.is_(None), or_(
        Notification.body.is_distinct_from(stmt.excluded.body), Notification.title.is_distinct_from(stmt.excluded.title)))
    # Preserve snoozes on text refresh, but a changed deadline re-arms delivery at the current time.
    stmt = stmt.on_conflict_do_update(index_elements=["key"],
                                     set_={**values, "delivered_at": None,
                                           "deliver_after": case((changed_date, stmt.excluded.deliver_after),
                                                                 else_=Notification.deliver_after)},
                                     where=or_(changed_date, pending_text))
    # rowcount is -1 here (driver + RETURNING); a returned id is the reliable "it was new".
    return session.scalar(stmt.returning(Notification.id)) is not None


def _end_of_day(day: date, tz: ZoneInfo) -> datetime:
    return datetime.combine(day + timedelta(days=1), time(0), tz)


def important_change(session: Session, change: Change, now: datetime) -> bool:
    """Prioritize changed imminent assessments/deadlines, including a date moved away."""
    if change.entity == "event":
        row = session.get(Event, change.entity_id) if change.entity_id else None
        if not row or row.kind != "exam":
            return False
        key, at, hours = "starts_at", row.starts_at, 72
    elif change.entity == "task":
        row = session.get(Task, change.entity_id) if change.entity_id else None
        if not row or row.status not in OPEN_STATUSES:
            return False
        key, at, hours = "due_at", row.due_at, 24
    else:
        return False
    dates = [at]
    for value in (change.detail or {}).get(key, []):
        if isinstance(value, str):
            try:
                parsed = datetime.fromisoformat(value)
                if parsed.tzinfo is not None:
                    dates.append(parsed)
            except ValueError:
                pass
    return any(d and now <= d <= now + timedelta(hours=hours) for d in dates)


def briefing_text(session: Session, now: datetime, tz: ZoneInfo) -> str:
    day = now.astimezone(tz).date()
    start, end = datetime.combine(day, time(0), tz), _end_of_day(day, tz)
    events = session.scalars(select(Event).where(Event.starts_at >= start, Event.starts_at < end)).all()
    open_tasks = session.scalars(select(Task).where(Task.status.in_(OPEN_STATUSES))).all()
    classes = sum(e.kind == "class" for e in events)
    exams = sum(e.kind == "exam" for e in events)
    due_today = sum(1 for t in open_tasks if t.due_at and now <= t.due_at < end)
    overdue = sum(1 for t in open_tasks if t.due_at and t.due_at < now)

    agenda = [p for p in (classes and _plural(classes, "aula", "aulas"), exams and _plural(exams, "avaliação", "avaliações")) if p]
    lines = [f"Hoje tens {_join(agenda)}." if agenda else "Hoje não tens aulas nem avaliações."]
    pending = [p for p in (due_today and _plural(due_today, "entrega para hoje", "entregas para hoje"),
                           overdue and _plural(overdue, "tarefa em atraso", "tarefas em atraso")) if p]
    if pending:
        lines.append(f"Tens {_join(pending)}.")
    upcoming = sorted((t for t in open_tasks if t.due_at and end <= t.due_at < end + timedelta(days=6)), key=lambda t: t.due_at)
    if upcoming:
        lines.append(f"Próximo prazo: {upcoming[0].title}, {_when(upcoming[0].due_at, now, tz)}.")
    from peace.academic import recommendation
    if rec := recommendation(session, now, planner_prefs(session), tz):
        lines.append(rec["text"])
    return " ".join(lines)


def generate(session: Session, now: datetime, tz: ZoneInfo) -> int:
    """Create every notification that is due now. Returns how many were new."""
    prefs = notify_prefs(session)
    if not prefs.enabled:
        return 0
    today = now.astimezone(tz).date()
    made = 0

    if prefs.deadlines:
        due_soon = session.scalars(
            select(Task).where(Task.status.in_(OPEN_STATUSES), Task.due_at > now, Task.due_at <= now + timedelta(hours=24))
        ).all()
        for t in due_soon:
            close = t.due_at - now <= timedelta(hours=2)
            course = f" · {t.course.name}" if t.course else ""
            made += _add(
                session,
                key=f"task:{t.id}:{'2h' if close else '24h'}",
                kind="deadline",
                title="Entrega em menos de 2 horas" if close else "Entrega nas próximas 24 horas",
                body=f"{t.title}{course} · {_when(t.due_at, now, tz)}",
                url="/prazos",
                actions=["open", "done", "snooze"],
                urgent=close,
                task_id=t.id,
                expires_at=t.due_at,
            )
        exams = session.scalars(
            select(Event).where(Event.kind == "exam", Event.starts_at > now, Event.starts_at <= now + timedelta(hours=24))
        ).all()
        for e in exams:
            close = e.starts_at - now <= timedelta(hours=2)
            made += _add(
                session,
                key=f"exam:{e.id}:{'2h' if close else '24h'}",
                kind="exam",
                title="Avaliação em menos de 2 horas" if close else "Avaliação nas próximas 24 horas",
                body=f"{e.title} · {_when(e.starts_at, now, tz)}" + (f" · {e.location}" if e.location else ""),
                url=f"/cadeiras/{e.course_id}" if e.course_id else "/prazos",
                actions=["open"],
                urgent=close,
                expires_at=e.starts_at,
            )

    if prefs.sessions:
        starting = session.scalars(
            select(StudySession).where(
                StudySession.status == "planned",
                StudySession.starts_at >= now - timedelta(minutes=2),
                StudySession.starts_at <= now + timedelta(minutes=5),
            )
        ).all()
        index = load_index(session) if starting else None
        for s in starting:
            minutes = int((s.ends_at - s.starts_at).total_seconds() // 60)
            picks = suggest(index, s.task) if s.task else suggest_text(index, s.event.title, s.event.course_id, "exam") if s.event else []
            made += _add(
                session,
                key=f"session:{s.id}:start",
                kind="session",
                title="Hora de estudar",
                body=f"{s.task.title if s.task else s.event.title if s.event else 'Sessão de estudo'} · {minutes} min" + (f" · {s.reason}" if s.reason else "")
                + (f"\nEstudar: {picks[0]['title']}" if picks else ""),
                url="/estudo",
                actions=["open", "skip", "snooze"],
                session_id=s.id,
                task_id=s.task_id,
                expires_at=s.ends_at,
            )

    if prefs.changes:
        # "changes:<last change id>" keys record how far change notifications have got.
        notified = session.scalar(
            select(func.max(func.split_part(Notification.key, ":", 2).cast(Integer)))
            .where(Notification.kind == "changes", Notification.key.regexp_match("^changes:[0-9]+$"))
        ) or 0
        fresh = session.scalars(select(Change).where(Change.seen_at.is_(None), Change.id > notified).order_by(Change.id)).all()
        if fresh:
            lines = [c.summary for c in fresh[:3]] + ([f"+{len(fresh) - 3} outras"] if len(fresh) > 3 else [])
            plans = sum(c.source == "planner" and c.entity == "plan" for c in fresh)
            made += _add(
                session,
                key=f"changes:{fresh[-1].id}",
                kind="changes",
                title="Plano de estudo atualizado" if plans == len(fresh) else "Alterações no plano e nas cadeiras" if plans
                else "Novidades nos sites" if len(fresh) > 1 else "Novidade nos sites",
                body="\n".join(lines),
                url="/atividade",
                actions=["open"],
                urgent=any(important_change(session, c, now) for c in fresh),
                expires_at=now + timedelta(days=2),
            )

    plan = planner_prefs(session)
    if prefs.missed and now.astimezone(tz).time() >= plan.study_end:
        start = datetime.combine(today, time(0), tz)
        missed = session.scalar(
            select(func.count()).select_from(StudySession).where(
                StudySession.status == "planned", StudySession.starts_at >= start, StudySession.ends_at <= now
            )
        )
        if missed:
            made += _add(
                session,
                key=f"missed:{today}",
                kind="missed",
                title="Ficou estudo por fazer",
                body=f"{_plural(missed, 'sessão ficou', 'sessões ficaram')} por fazer hoje. Queres replanear amanhã?",
                url="/estudo",
                actions=["replan", "open"],
                expires_at=_end_of_day(today + timedelta(days=1), tz),
            )

    if prefs.integrations:
        for health in sync.status(session, now, next_run=now):  # next_run is not used here
            if health["needs_login"] or (health["stale"] and health["last_status"] is not None):
                name = {"inforestudante": "Inforestudante", "moodle": "Moodle"}.get(health["source"], health["source"])
                made += _add(
                    session,
                    key=f"sync:{health['source']}:{today}",
                    kind="integration",
                    title=f"{name}: sincronização com problemas",
                    body="O login foi recusado. Verifica as credenciais." if health["needs_login"] else "Os dados podem estar desatualizados.",
                    url="/definicoes",
                    actions=["open"],
                    expires_at=_end_of_day(today, tz),
                )

    if now.astimezone(tz).time() >= prefs.briefing_at:
        made += _add(
            session,
            key=f"briefing:{today}",
            kind="briefing",
            title="O teu dia",
            body=briefing_text(session, now, tz),
            url="/",
            actions=["open"],
            expires_at=_end_of_day(today, tz),
        )
    return made
